# bfs girth
INF=999
best=INF
for s in range(N):
    dist=[-1]*N; par=[-1]*N
    dist[s]=0; q=collections.deque([s])
    while q:
        u=q.popleft()
        for v in adj[u]:
            if dist[v]<0:
                dist[v]=dist[u]+1; par[v]=u; q.append(v)
